/**
 * A member's plain text as paragraphs, with line breaks kept and web links
 * made clickable. Built from text nodes and Mithril elements, never HTML, so
 * nothing a member types can become markup.
 */
const LINK = /(https?:\/\/[^\s<>"']+[^\s<>"'.,;:!?)\]])/g;
function line(text) {
  return text.split(LINK).map((part, i) => i % 2 ? m("a", {
    href: part,
    target: "_blank",
    rel: "ugc noopener nofollow"
  }, part) : part);
}
export default function richText(text) {
  if (!text) return null;
  return text.replace(/\r\n/g, '\n').split(/\n{2,}/).filter(p => p.trim()).map(paragraph => m("p", null, paragraph.split('\n').flatMap((l, i) => i ? [m("br", null), ...line(l)] : line(l))));
}